import{d as g,C as o,o as h,c as d,j as i,a as e,E as a,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"中庸·第28章","description":"《中庸》第 28 章——愚而好自用：非天子不议礼、不制度、不考文；虽有其位，苟无其德，不敢作礼乐；吾学周礼，今用之，吾从周。","frontmatter":{"title":"中庸·第28章","description":"《中庸》第 28 章——愚而好自用：非天子不议礼、不制度、不考文；虽有其位，苟无其德，不敢作礼乐；吾学周礼，今用之，吾从周。","category":"guide","aliases":["第28章","中庸第28章","愚而好自用"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-28.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-28.md","lastUpdated":1790316338000}'),u={name:"lizhimingde/sishu-wujing/zhongyong/chapter-28.md"},f=g({...u,setup(p){const r=[{id:"ziyong",label:"愚而好自用 · 贱而好自专 · 菑及其身",showLabel:!0,sentences:[["子曰：“愚而好",{text:"自用",glossary:"ziyong"},"，贱而好",{text:"自专",glossary:"zizhuan"},"，生乎今之世，",{text:"反古之道",glossary:"fanguzhidao"},"。如此者，",{text:"菑",glossary:"zai"},"及其身者也。”"]],note:"孔子说：「愚而好自用，贱而好自专」——愚昧而好自作主张，卑贱而好独断独行；又「生乎今之世，反古之道」——生在当今之世，却要恢复古制。「如此者，菑及其身者也」——灾祸必落到他身上。"},{id:"feitianzi",label:"非天子不议礼 · 车同轨，书同文，行同伦",showLabel:!0,sentences:[["非天子，不",{text:"议礼",glossary:"yili"},"，不制度，不考文。今天下车同轨，书同文，行同伦。虽有其位，苟无其德，不敢作礼乐焉；虽有其德，苟无其位，亦不敢作礼乐焉。"]],note:"「非天子，不议礼，不制度，不考文」——不是天子，就不议礼、不定制度、不考订文字。「今天下车同轨，书同文，行同伦」——如今车轨相同、文字相同、伦理相同。又：虽有其位而无其德，不敢作礼乐；虽有其德而无其位，亦不敢作礼乐。"},{id:"wucongzhou",label:"吾说夏礼 · 吾学周礼，吾从周",showLabel:!0,sentences:[["子曰：“吾说夏礼，",{text:"杞",glossary:"qi"},"不足",{text:"征",glossary:"zheng"},"也；吾学殷礼，有宋存焉；吾学周礼，今用之，吾从周。”"]],note:"孔子说：我能说夏礼，但杞国不足以取证；我学殷礼，宋国尚存其遗；我学周礼——周礼正为今日所用，故「吾从周」。"}],s=[{id:"ziyong",term:"自用",pinyin:"zì yòng",meaning:"自以为是，凭己意行事。"},{id:"zizhuan",term:"自专",pinyin:"zì zhuān",meaning:"自作主张、独断。"},{id:"fanguzhidao",term:"反古之道",pinyin:"fǎn gǔ zhī dào",meaning:"反：复。要回复古道。"},{id:"zai",term:"菑",pinyin:"zāi",meaning:"古「灾」字。"},{id:"yili",term:"议礼",pinyin:"yì lǐ",meaning:"议定亲疏贵贱相接之体。"},{id:"zhidu",term:"制度",pinyin:"zhì dù",meaning:"制定品制法度。"},{id:"kaowen",term:"考文",pinyin:"kǎo wén",meaning:"考定书名文字。三者皆天子之事。"},{id:"qi",term:"杞",pinyin:"qǐ",meaning:"夏之后代之国。"},{id:"zheng",term:"征",pinyin:"zhēng",meaning:"证明、考据。"}];return(y,n)=>{const l=o("DaoTextReading"),t=o("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第28章",tabindex:"-1"},[e("中庸·第28章 "),i("a",{class:"header-anchor",href:"#中庸·第28章","aria-label":'Permalink to "中庸·第28章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[e("第二十八章先引孔子说三种自取灾祸的人，再立一条制度原则——"),i("strong",null,"非天子不议礼、不制度、不考文"),e("；接着讲「"),i("strong",null,"虽有其位，苟无其德"),e("（或反之）都不敢作礼乐」；末以孔子「吾从周」作结。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),a(l,{colophon:"愚而好自用 · 非天子不议礼 · 吾从周",tone:"ink",sections:r,glossary:s,"default-mode":"slips","aria-label":"中庸·第28章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(t,{items:[{term:"自用",pinyin:["zì","yòng"],meaning:"凭己意行事。"},{term:"自专",pinyin:["zì","zhuān"],meaning:"自作主张、独断。加在「愚」「贱」上，就是位置与主张不符。"},{term:"菑",pinyin:["zāi"],meaning:"古「灾」字。"},{term:"议礼",pinyin:["yì","lǐ"],meaning:"议定亲疏贵贱相接之体。"},{term:"制度",pinyin:["zhì","dù"],meaning:"制定品制法度。"},{term:"考文",pinyin:["kǎo","wén"],meaning:"考定书名文字。三者皆天子之事。"},{term:"车同轨",pinyin:["chē","tóng","guǐ"],meaning:"车同辙迹。"},{term:"书同文",pinyin:["shū","tóng","wén"],meaning:"书同文字。"},{term:"行同伦",pinyin:["xíng","tóng","lún"],meaning:"行同次序。三者皆言天下一统。"}]}),a(t,{items:[{term:"虽有其位",pinyin:["suī","yǒu","qí","wèi"],meaning:"虽有天子的位置。"},{term:"苟无其德",pinyin:["gǒu","wú","qí","dé"],meaning:"如果没有那德，就不敢作礼乐；反之亦然——德与位须相配。"},{term:"吾从周",pinyin:["wú","cóng","zhōu"],meaning:"孔子既不得位，则从时王之制（周礼）而不自作。知道自己的位置，所以说「从」不说「作」。"}]}),n[4]||(n[4]=m('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>愚而好自用 · 菑及其身</strong>：孔子说：「愚昧而好自以为是，卑贱而好自作主张，生在当今之世却要回复古道——这样的人，灾祸会落到他身上。」</p><p><strong>非天子不议礼</strong>：不是天子，不议定礼制，不制定法度，不考定文字。如今天下车同轨、书同文、行同伦。虽有天子的位置，如果没有那德，不敢制作礼乐；虽有那德，如果没有那位，也不敢制作礼乐。</p><p><strong>吾说夏礼 · 吾从周</strong>：孔子说：「我能讲夏礼，但杞国不足以考据；我学过殷礼，宋国还存有它；我学周礼，如今正在用——我遵从周。」</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第二十八章三段：</p><ol><li><strong>三种自取灾祸的人</strong>：愚而好自用、贱而好自专、生今之世反古之道</li><li><strong>制度的原则</strong>：非天子不议礼、不制度、不考文；且「有德无位／有位无德」都不敢作礼乐</li><li><strong>孔子的榜样</strong>：夏礼不可考、殷礼虽存非当世之法，于是「吾从周」</li></ol><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>前三条病其实是同一种病</strong>：都是<strong>主张超出了自己的位置</strong>——愚者自用（才不够而主意大）、贱者自专（位不够而主张大）、生今反古（时不对而复古）。朱注点明后两条是「子思引孔子之言」，本章其实是在讲<strong>分寸</strong>。</li><li><strong>「非天子不议礼」不是说知识不够，而是位置不对</strong>：制度、法度、文字，是要通行天下的东西，故须有相应之权。这一条与第 20 章「为政在人」同属「谁来做」的问题。</li><li><strong>「德位相配」是全章最实的一句</strong>：有位无德、有德无位，都不敢作礼乐——<strong>少一样都不行</strong>。这与第 27 章「苟不至德，至道不凝」互为注脚。</li><li><strong>「吾从周」是全篇极见分寸的一句</strong>：以孔子之德，若说「我来作」，也说得过去；但他选择了「从」。<strong>知道该「从」而不该「作」，是一种更高的自觉。</strong></li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>对表三条病</strong>：我有没有在自己不够的地方「自用」，在自己没权的地方「自专」？</li><li><strong>「德位相配」</strong>：想推动一项改变，先看自己的德与位各到什么程度。</li><li><strong>「吾从周」</strong>：清楚哪些事情该我说了算，哪些事情该跟着既定之制走。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>孔子先说三种人要倒霉：<strong>笨却爱自作主张，没位置却爱拍板，活在今天却非要恢复古时那一套。</strong></p><p>接着是一条制度原则：<strong>议礼、定法度、考文字，这些不是天子不能做</strong>——因为天下车同轨、书同文，制度是要通行天下的东西。而且就算坐在那位子上，没有那个德，不敢作礼乐；有那个德，不在那位子上，也不敢作。</p><p>最后孔子自己做示范：夏礼讲得出，但没证据；殷礼有宋国在存着；周礼现在正在用——<strong>那我就遵从周礼。</strong></p><p>这一章说的其实是「分寸」：<strong>主张不要超出自己的位置，也不要少于自己的德。</strong></p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「愚而好自用，贱而好自专」——我有没有在自己不够的地方「自用」、在自己没权的地方「自专」？</li><li>「虽有其位，苟无其德」与「虽有其德，苟无其位」——我现在缺的是哪一样？</li><li>「吾从周」——哪些事该我说了算，哪些事该「从」？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-27">中庸·第27章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-29">中庸·第29章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',24))])}}});export{c as __pageData,f as default};
